using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.Globalization;
using System.IO;
using System.Text;
using System.Linq;
using System.Windows.Forms;
namespace CircuitoStudio {
public sealed class CableOption {
[DisplayName("Nome")] public string Name {get;set;}
[DisplayName("Material")] public string Material {get;set;}
[DisplayName("Isolação")] public string Insulation {get;set;}
[DisplayName("Instalação")] public string Installation {get;set;}
[DisplayName("Referência")] public string Reference {get;set;}
[DisplayName("Seção (mm²)")] public double SectionMm2 {get;set;}
[DisplayName("Iz tabela (A)")] public double IzA {get;set;}
[DisplayName("R (Ω/km)")] public double ResistanceOhmKm {get;set;}
[DisplayName("X (Ω/km)")] public double ReactanceOhmKm {get;set;}
public CableOption(){Name=Material=Insulation=Installation=Reference="";}
public void Validate(){foreach(string s in new[]{Name,Material,Insulation,Installation,Reference})if(String.IsNullOrWhiteSpace(s)||s.Length>2000||s.IndexOf('\0')>=0)throw new InvalidDataException("Todos os textos são obrigatórios (máximo 2000 caracteres).");if(Material!="Copper"&&Material!="Aluminium"&&Material!="Cu"&&Material!="Al")throw new InvalidDataException("Material deve ser Cu, Al, Copper ou Aluminium.");if(Insulation!="PVC"&&Insulation!="XLPE")throw new InvalidDataException("Isolação deve ser PVC ou XLPE.");foreach(double n in new[]{SectionMm2,IzA,ResistanceOhmKm,ReactanceOhmKm})if(Double.IsNaN(n)||Double.IsInfinity(n)||n<0)throw new InvalidDataException("Números devem ser finitos e não negativos.");if(SectionMm2<=0||IzA<=0)throw new InvalidDataException("Seção e ampacidade devem ser positivas.");}
public bool Copper {get{return Material=="Cu"||Material=="Copper";}}
}
public sealed class CableEvaluation {
[Browsable(false)] public CableOption Cable {get;set;}
[DisplayName("Nome")] public string Name {get;set;}
[DisplayName("Seção mm²")] public double Section {get;set;}
[DisplayName("Ib (A)")] public double Ib {get;set;}
[DisplayName("Iz corrigida (A)")] public double? Iz {get;set;}
[DisplayName("Queda local (%)")] public double Drop {get;set;}
[DisplayName("Resultado local")] public string Status {get;set;}
[DisplayName("Detalhes e pendências")] public string Detail {get;set;}
}
public static class CableSelection {
public const string Header="Name;Material;Insulation;Installation;SectionMm2;IzA;ResistanceOhmKm;ReactanceOhmKm;Reference";
static List<string[]> Rows(string text){var rows=new List<string[]>();var cells=new List<string>();var b=new StringBuilder();bool quoted=false,closed=false,start=true;for(int i=0;i<text.Length;i++){char c=text[i];if(quoted){if(c=='"'){if(i+1<text.Length&&text[i+1]=='"'){b.Append('"');i++;}else{quoted=false;closed=true;}}else b.Append(c);continue;}if(c=='"'){if(!start||closed)throw new InvalidDataException("Aspas inválidas.");quoted=true;start=false;continue;}if(c==';'||c=='\r'||c=='\n'){cells.Add(b.ToString());b.Length=0;start=true;closed=false;if(c!=';'){if(c=='\r'&&i+1<text.Length&&text[i+1]=='\n')i++;rows.Add(cells.ToArray());cells.Clear();}continue;}if(closed)throw new InvalidDataException("Texto após aspas.");b.Append(c);start=false;}if(quoted)throw new InvalidDataException("Aspas não terminadas.");if(b.Length>0||cells.Count>0||closed){cells.Add(b.ToString());rows.Add(cells.ToArray());}return rows;}
static double Number(string s){s=s.Trim();double n;if(s.Contains(".")&&s.Contains(","))throw new InvalidDataException("Número ambíguo: "+s);if(!Double.TryParse(s.Replace(',','.'),NumberStyles.AllowLeadingSign|NumberStyles.AllowDecimalPoint|NumberStyles.AllowExponent,CultureInfo.InvariantCulture,out n)||Double.IsInfinity(n)||Double.IsNaN(n))throw new InvalidDataException("Número inválido: "+s);return n;}
static List<CableOption> ImportRows(List<string[]> rows){if(rows.Count>100000)throw new InvalidDataException("A tabela excede 100000 linhas.");if(rows.Count==0||String.Join(";",rows[0])!=Header)throw new InvalidDataException("Cabeçalho incompatível. Exporte o modelo vazio.");var list=new List<CableOption>();var keys=new HashSet<string>(StringComparer.OrdinalIgnoreCase);for(int i=1;i<rows.Count;i++){try{var r=rows[i];if(r.Length!=9)throw new InvalidDataException("Esperadas 9 colunas.");var c=new CableOption{Name=r[0],Material=r[1],Insulation=r[2],Installation=r[3],SectionMm2=Number(r[4]),IzA=Number(r[5]),ResistanceOhmKm=Number(r[6]),ReactanceOhmKm=Number(r[7]),Reference=r[8]};c.Validate();string key=(c.Copper?"Cu":"Al")+"\0"+c.Insulation+"\0"+c.Installation.Trim()+"\0"+c.Name.Trim()+"\0"+c.SectionMm2.ToString("R",CultureInfo.InvariantCulture)+"\0"+c.Reference.Trim();if(!keys.Add(key))throw new InvalidDataException("Item duplicado.");list.Add(c);}catch(Exception e){throw new InvalidDataException("Registro "+(i+1)+": "+e.Message,e);}}list.Sort(delegate(CableOption a,CableOption b){return a.SectionMm2.CompareTo(b.SectionMm2);});return list;}
public static List<CableOption> ImportCsv(string file){if(new FileInfo(file).Length>32*1024*1024)throw new InvalidDataException("Arquivo CSV maior que 32 MiB.");return ImportRows(Rows(File.ReadAllText(file,Encoding.UTF8).TrimStart('\uFEFF')));}
public static List<CableOption> ImportXlsx(string file){return ImportRows(XlsxWorkbook.ReadRows(file));}
public static List<CableOption> ImportXls(string file){return ImportRows(LegacyXls.ReadRows(file));}
public static List<CableOption> ImportTable(string file){switch(Path.GetExtension(file).ToLowerInvariant()){case ".xls":return ImportXls(file);case ".xlsx":return ImportXlsx(file);case ".csv":return ImportCsv(file);default:throw new InvalidDataException("Escolha um arquivo CSV, XLS ou XLSX.");}}
static string Q(string s){return "\""+s.Replace("\"","\"\"")+"\"";}
public static void ExportCsv(List<CableOption> items,string file){string full=Path.GetFullPath(file);Directory.CreateDirectory(Path.GetDirectoryName(full));string tmp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var w=new StreamWriter(tmp,false,new UTF8Encoding(true))){w.WriteLine(Header);foreach(var c in items){c.Validate();string[] r={c.Name,c.Material,c.Insulation,c.Installation,c.SectionMm2.ToString("R",CultureInfo.InvariantCulture),c.IzA.ToString("R",CultureInfo.InvariantCulture),c.ResistanceOhmKm.ToString("R",CultureInfo.InvariantCulture),c.ReactanceOhmKm.ToString("R",CultureInfo.InvariantCulture),c.Reference};for(int i=0;i<r.Length;i++)r[i]=Q(r[i]);w.WriteLine(String.Join(";",r));}}ImportCsv(tmp);if(File.Exists(full))File.Replace(tmp,full,null);else File.Move(tmp,full);}finally{if(File.Exists(tmp))File.Delete(tmp);}}
public static void ExportXlsx(List<CableOption> items,string file){var rows=new List<string[]>{Header.Split(';')};foreach(var c in items){c.Validate();rows.Add(new[]{c.Name,c.Material,c.Insulation,c.Installation,c.SectionMm2.ToString("R",CultureInfo.InvariantCulture),c.IzA.ToString("R",CultureInfo.InvariantCulture),c.ResistanceOhmKm.ToString("R",CultureInfo.InvariantCulture),c.ReactanceOhmKm.ToString("R",CultureInfo.InvariantCulture),c.Reference});}ImportRows(rows);XlsxWorkbook.Write(file,rows);}
public static bool Matches(CableOption o,Circuit c){return o.Copper==(c.Cable.Material==ConductorMaterial.Copper)&&o.Insulation==c.Cable.Insulation.ToString()&&String.Equals(o.Installation.Trim(),(c.Cable.InstallationMethod??"").Trim(),StringComparison.OrdinalIgnoreCase);}
public static CableEvaluation Evaluate(Project p,Circuit c,CableOption o){if(p==null||c==null||o==null)throw new InvalidDataException("Projeto, circuito ou cabo ausente.");return EvaluateKnown(p,c,o,Engineering.Analyze(p).For(c));}
internal static CableEvaluation EvaluateKnown(Project p,Circuit c,CableOption o,CircuitResult load){o.Validate();if(!Matches(o,c))throw new InvalidDataException("Material, isolação ou instalação incompatível com o circuito.");var a=c.Cable;foreach(double v in new[]{a.TemperatureFactor,a.GroupingFactor,c.Voltage,c.LengthM,c.PowerFactor,c.PowerKw,c.DemandFactor,c.BreakerA})if(Double.IsNaN(v)||Double.IsInfinity(v))throw new InvalidDataException("Dados numéricos do circuito não finitos.");if(a.Parallel<1||a.TemperatureFactor<=0||a.GroupingFactor<=0||c.Voltage<=0||c.LengthM<0||p.Source==null||(c.VoltageDropLimitPercent??p.Source.MaxDropPercent)<=0||c.PowerFactor<=0||c.PowerFactor>1)throw new InvalidDataException("Revise tensão, fatores, paralelos, comprimento e limites do circuito.");if(load==null)throw new InvalidDataException("Circuito ausente do projeto.");double kw=load.DemandKw,kvar=load.ReactiveKvar;double kva=Math.Sqrt(kw*kw+kvar*kvar),pf=kva>0?kw/kva:1;double ib=load.CurrentA;double iz=o.IzA*a.TemperatureFactor*a.GroupingFactor*a.Parallel;string correctionDetail;bool correctionApplies=CableFactors.Applicable(c,o,out correctionDetail);double r=o.ResistanceOhmKm>0?o.ResistanceOhmKm:(o.Copper?23.7:37.6)/o.SectionMm2;double drop=100*(c.Phases==PhaseMode.Trifasico?Math.Sqrt(3):2)*ib*c.LengthM/1000/a.Parallel*(r*pf+o.ReactanceOhmKm*(kva>0?kvar/kva:0))/c.Voltage;bool fail=(correctionApplies&&ib>iz)||Math.Abs(drop)>(c.VoltageDropLimitPercent??p.Source.MaxDropPercent);var pending=new List<string>();var details=new List<string>();if(!correctionApplies)pending.Add(correctionDetail);details.Add(CableFactors.Describe(c));details.Add("Iz = tabela × temperatura × agrupamento × paralelos. Queda local; limite "+(c.VoltageDropLimitPercent??p.Source.MaxDropPercent).ToString("0.##")+"%.");if(c.BreakerA>0){if(ib>c.BreakerA||(correctionApplies&&c.BreakerA>iz))fail=true;}else pending.Add("corrente nominal da proteção");var pr=c.Protection;if(pr!=null&&pr.ConventionalTripA>0&&correctionApplies){if(pr.ConventionalTripA>1.45*iz)fail=true;}else pending.Add("I2 da proteção");if(pr!=null&&pr.LetThroughA2s>0&&a.Parallel==1&&pr.DisconnectSeconds>0&&pr.DisconnectSeconds<=5){double k=o.Copper?(o.Insulation=="PVC"?115:143):(o.Insulation=="PVC"?76:94);if(o.Insulation=="PVC"&&o.SectionMm2>300)k=o.Copper?103:68;if(pr.LetThroughA2s>Math.Pow(k*o.SectionMm2,2))fail=true;details.Add("Térmico: I²t ≤ (kS)², k="+k+"; confirmar temperaturas e curva.");}else pending.Add("suportabilidade térmica (I²t, tempo 0<t≤5 s e um paralelo necessários)");bool upstream=false;foreach(var b in p.Boards)if(b.Circuits.Contains(c)){foreach(var pb in p.Boards)foreach(var pc in pb.Circuits)if(pc.ChildBoardId==b.Id)upstream=true;}if(upstream)pending.Add("queda de tensão a montante/acumulada");details.Add("Demais verificações de curto, proteção e topologia serão refeitas no estudo completo; pré-seleção sem certificação normativa.");if(pending.Count>0)details.Add("Pendências: "+String.Join("; ",pending.ToArray())+".");return new CableEvaluation{Cable=o,Name=o.Name,Section=o.SectionMm2,Ib=ib,Iz=correctionApplies?(double?)iz:null,Drop=drop,Status=fail?"Não atende":pending.Count>0?"Dados incompletos":"Atende verificações locais",Detail=String.Join(" ",details.ToArray())};}
public static CableEvaluation Recommend(Project project,Circuit circuit,IEnumerable<CableOption> options){
 if(project==null||circuit==null||options==null)throw new InvalidDataException("Projeto, circuito ou tabela ausente.");project.Validate();if(!project.Boards.Any(board=>board.Circuits.Contains(circuit)))throw new InvalidDataException("Circuito fora do projeto.");if(circuit.Cable.FactorsSnapshot==null)return null;var load=Engineering.Analyze(project).For(circuit);if(load.CurrentA<=0&&circuit.BreakerA<=0)return null;var candidates=options.ToList();if(candidates.Count>100000)throw new InvalidDataException("Tabela excede 100000 candidatos.");foreach(var candidate in candidates){if(candidate==null)throw new InvalidDataException("Cabo ausente.");candidate.Validate();}
 foreach(var candidate in candidates.Where(option=>Matches(option,circuit)).OrderBy(option=>option.SectionMm2).ThenBy(option=>option.IzA)){
  var evaluation=EvaluateKnown(project,circuit,candidate,load);if(evaluation.Iz.HasValue&&evaluation.Status!="Não atende"&&evaluation.Ib<=evaluation.Iz.Value){evaluation.Detail="Menor seção dentre os candidatos da tabela que passa nas verificações locais disponíveis. Seção "+candidate.SectionMm2+" mm²; Iz tabela="+candidate.IzA+" A; Iz corrigida="+evaluation.Iz.Value+" A; instalação "+candidate.Installation+"; fonte "+candidate.Reference+". "+evaluation.Detail;return evaluation;}
 }
 return null;
}
}
public sealed class CableSelectionForm:Form {
Project project;Circuit circuit;string file;List<CableOption> items;DataGridView grid;Label note;TextBox details;CableEvaluation recommendation;
public CableOption SelectedCable {get;private set;}
public CableSelectionForm(Project p,Circuit c,string catalogueFile){project=p;circuit=c;file=catalogueFile;items=File.Exists(file)?CableSelection.ImportCsv(file):new List<CableOption>();Text="Pré-seleção de cabos — tabela informada";Size=new Size(1150,680);MinimumSize=new Size(900,500);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(238,244,248);var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=55,Padding=new Padding(10),BackColor=Color.FromArgb(20,39,60)};Add(top,"Importar planilha",Import);Add(top,"Exportar modelo vazio",Template);Add(top,"Aplicar pré-seleção",Apply);Add(top,"Pré-selecionar menor seção",RecommendChoice);note=new Label{Dock=DockStyle.Top,Height=76,Padding=new Padding(12)};details=new TextBox{Dock=DockStyle.Bottom,Height=110,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=Color.White};grid=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells,BackgroundColor=Color.White};grid.SelectionChanged+=delegate{var x=Current();details.Text=x==null?"":recommendation!=null&&Object.ReferenceEquals(x.Cable,recommendation.Cable)?recommendation.Detail:x.Detail;};Controls.Add(grid);Controls.Add(details);Controls.Add(note);Controls.Add(top);RefreshRows();}
void Add(FlowLayoutPanel panel,string text,Action action){var b=new Button{Text=text,AutoSize=true,BackColor=Color.FromArgb(22,134,139),ForeColor=Color.White,FlatStyle=FlatStyle.Flat};b.Click+=delegate{try{action();}catch(Exception e){MessageBox.Show(this,e.Message,"Pré-seleção",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};panel.Controls.Add(b);}
CableEvaluation Current(){return grid.CurrentRow==null?null:grid.CurrentRow.DataBoundItem as CableEvaluation;}
void RefreshRows(){recommendation=null;var results=new List<CableEvaluation>();var load=Engineering.Analyze(project).For(circuit);foreach(var o in items)if(CableSelection.Matches(o,circuit))results.Add(CableSelection.EvaluateKnown(project,circuit,o,load));grid.DataSource=new BindingList<CableEvaluation>(results);foreach(string name in new[]{"Section","Ib","Iz","Drop"})if(grid.Columns.Contains(name))grid.Columns[name].DefaultCellStyle.Format="0.###";note.Text="Filtro: "+circuit.Cable.Material+" / "+circuit.Cable.Insulation+" / instalação: "+circuit.Cable.InstallationMethod+". "+results.Count+" opções compatíveis de "+items.Count+".\r\n"+(items.Count==0?"Exporte o modelo e preencha com ampacidades, condições de instalação e referências verificadas. Nenhuma tabela de ampacidade é fornecida.":"Só são comparadas condições de instalação iguais. Revise fatores de correção no circuito antes de aplicar.");}
void Import(){using(var d=new OpenFileDialog{Filter="Planilhas (*.xls;*.xlsx;*.csv)|*.xls;*.xlsx;*.csv|Excel legado (*.xls)|*.xls|Excel (*.xlsx)|*.xlsx|CSV (*.csv)|*.csv"})if(d.ShowDialog(this)==DialogResult.OK){var imported=CableSelection.ImportTable(d.FileName);if(items.Count>0&&MessageBox.Show(this,"Substituir a tabela atual pelas "+imported.Count+" opções importadas?","Importar tabela",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;foreach(var o in imported)if(CableSelection.Matches(o,circuit))CableSelection.Evaluate(project,circuit,o);CableSelection.ExportCsv(imported,file);items=imported;RefreshRows();}}
void Template(){using(var d=new SaveFileDialog{Filter="Excel (*.xlsx)|*.xlsx|CSV (*.csv)|*.csv",FileName="modelo-cabos.xlsx"})if(d.ShowDialog(this)==DialogResult.OK){if(String.Equals(Path.GetFullPath(d.FileName),Path.GetFullPath(file),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Escolha outro nome para o modelo; preserve seu catálogo ativo.");if(String.Equals(Path.GetExtension(d.FileName),".csv",StringComparison.OrdinalIgnoreCase))CableSelection.ExportCsv(new List<CableOption>(),d.FileName);else CableSelection.ExportXlsx(new List<CableOption>(),d.FileName);}}
void RecommendChoice(){var recommended=CableSelection.Recommend(project,circuit,items);if(recommended==null){MessageBox.Show(this,"Nenhuma seção possui condições/fatores com referência compatível e atende às verificações locais disponíveis. Confira tabela, fatores, corrente, proteção e queda.","Pré-seleção de cabos",MessageBoxButtons.OK,MessageBoxIcon.Information);return;}recommendation=recommended;foreach(DataGridViewRow row in grid.Rows){var value=row.DataBoundItem as CableEvaluation;if(value!=null&&Object.ReferenceEquals(value.Cable,recommended.Cable)){grid.CurrentCell=row.Cells[0];row.Selected=true;details.Text=recommended.Detail;return;}}}
void Apply(){var e=Current();if(e==null)return;MessageBox.Show(this,e.Status+"\r\n\r\n"+e.Detail+"\r\n\r\nA seção será aplicada para revisão no estudo completo.","Resumo da pré-seleção",MessageBoxButtons.OK,MessageBoxIcon.Information);SelectedCable=e.Cable;DialogResult=DialogResult.OK;Close();}
}
}
